    "      \"surface\": \"r\",\n",
    "      \"repository\": \"nirs4all-r\",\n",
    "      \"package\": \"nirs4all\",\n",
    "      \"core_runtime_surface\": false,\n",
    "      \"status\": \"externally-federated\",\n",
    "      \"profiles\": [\n",
